"""Data quality findings generated by scheduled validation checks."""
import uuid
from datetime import datetime
from typing import Optional

from sqlalchemy import DateTime, Index, Integer, String, Text, func
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column

from .base import Base, UUIDMixin


class DataQualityIssue(Base, UUIDMixin):
    __tablename__ = "data_quality_issues"

    check_name: Mapped[str] = mapped_column(String(120), nullable=False, index=True)
    severity: Mapped[str] = mapped_column(String(20), nullable=False, index=True, default="warning")
    source: Mapped[Optional[str]] = mapped_column(String(50), nullable=True, index=True)
    competition_key: Mapped[Optional[str]] = mapped_column(String(60), nullable=True, index=True)
    entity_type: Mapped[str] = mapped_column(String(60), nullable=False)
    entity_id: Mapped[Optional[str]] = mapped_column(String(120), nullable=True)
    issue_count: Mapped[int] = mapped_column(Integer, nullable=False, default=1)
    sample: Mapped[Optional[dict]] = mapped_column(JSONB, nullable=True)
    message: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    detected_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now())
    run_id: Mapped[Optional[uuid.UUID]] = mapped_column(UUID(as_uuid=True), nullable=True, index=True)

    __table_args__ = (
        Index("ix_data_quality_main", "detected_at", "severity", "check_name"),
    )

